   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽说躲过了爆炸，但冲击波和后续异变体的踩踏还是重创了我。我的喉管被撕破，心脏也失去了活性。", msg_color="", msg_size=0, talker="弗丽达", audio="", img="arts/ui/bg/story/storybg_ACT209_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7143", 2, 0, 18.5, 195.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
